<?php
namespace App\Http\Controllers;
use App\Models\{Product,Category}; use Illuminate\Http\Request;
class StorefrontController extends Controller { public function home(){ $products=Product::with('category')->where('is_active',true)->where('featured',true)->latest()->take(6)->get(); $categories=Category::where('is_active',true)->withCount('products')->get(); return view('home',compact('products','categories')); } public function shop(Request $r){$q=$r->string('q')->toString();$cat=$r->string('category')->toString();$products=Product::with('category')->where('is_active',true)->when($q,fn($x)=>$x->where(fn($y)=>$y->where('name','ilike','%'.$q.'%')->orWhere('description','ilike','%'.$q.'%')))->when($cat,fn($x)=>$x->whereHas('category',fn($y)=>$y->where('slug',$cat)))->latest()->paginate(12)->withQueryString();$categories=Category::where('is_active',true)->get();return view('shop.index',compact('products','categories','q','cat'));} public function product(Product $product){abort_unless($product->is_active,404);return view('shop.show',compact('product'));} }
